    21	function validateCardNumber(value: string): boolean {
    22	    let sum = 0;
    23	    for (let i = 0; i < value.length; i++) {
    24	        let intVal = parseInt(value.substr(i, 1), 10);
    25	        if (i % 2 === 0) {
    26	            intVal *= 2;
    27	            if (intVal > 9) {
    28	                intVal = 1 + (intVal % 10);
    29	            }
    30	        }
    31	        sum += intVal;
    32	    }
    33	    return sum % 10 === 0;
